// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/establishments", wrapper.ListEstablishments)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/establishments/{establishmentId}/menu", wrapper.GetEstablishmentMenu)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/orders", wrapper.CreateOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/orders/status", wrapper.GetTrackedOrder)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/orders/cancel", wrapper.CancelOrder)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/partner/menu", wrapper.GetPartnerMenu)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/partner/categories", wrapper.CreateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/partner/categories/{categoryId}", wrapper.UpdateCategory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/partner/dishes", wrapper.CreateDish)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/partner/dishes/{dishId}", wrapper.UpdateDish)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/partner/establishment", wrapper.UpdateEstablishment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/partner/orders", wrapper.ListPartnerOrders)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/partner/orders/{orderId}", wrapper.GetPartnerOrder)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/partner/orders/{orderId}/status", wrapper.UpdatePartnerOrderStatus)
	})

	return r
}

